import React from "react";

interface WindowProps {
  progress?: number; // 0 to 100 (e.g. 0, 30, 60, 100)
  className?: string;
}

export default function Window({ progress = 0, className = "" }: WindowProps) {
  const normalizedProgress = Math.min(100, Math.max(0, progress));

  return (
    <div className={`relative inline-block w-full max-w-[363px] ${className}`}>
      {/* Background faint window contour (visible at 20% opacity) */}
      <div className="opacity-20 pointer-events-none">
        <WindowSVG />
      </div>

      {/* Progressively revealed rich window drawing (30% -> 60% -> 100%) */}
      <div
        className="absolute inset-0 transition-all duration-700 ease-out pointer-events-none"
        style={{
          clipPath: `inset(0 ${100 - normalizedProgress}% 0 0)`,
        }}
      >
        <WindowSVG />
      </div>
    </div>
  );
}

